  <button id="prevStep" style="flex:1">◀ Prev</button>
  <button id="nextStep" style="flex:1">Next ▶</button>
  <button id="playSteps" style="flex:1">Play</button>
</div>
<div id="stepTitle" style="font-weight:600;font-size:11px"></div>
<div id="stepText" style="font-size:11px;line-height:1.45;color:#333"></div>

<div style="font-size:10px;color:#666;margin-top:4px;line-height:1.4">
  Click either sphere to select it (its radius arrow thickens and its Q, V, σ are reported).
  Drag to orbit and see the “+” charges wrap around the 3D surfaces.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ─────────────────────────────────────────────────────────
   large sphere R1   → SphereGeometry(1,64,48) + MeshMatcapMaterial(lavender radial canvas)
   small sphere R2   → SphereGeometry(1,48,36) scaled, MeshMatcapMaterial(grey radial canvas)
   selection halo    → SphereGeometry(1) BackSide orange, scale 1.06R
   centre dots       → SphereGeometry(0.035 / 0.02) MeshBasicMaterial black
   radius arrows     → Group[ CylinderGeometry shaft + ConeGeometry head ] black
   '+' charges       → Sprite(CanvasTexture plus glyph), depthTest off, tweened positions
   wire              → 2 × TubeGeometry along QuadraticBezierCurve3, grey #8a8a8a, r=0.015
   R1,R2,V1,V2,σ     → addLabel HTML (italic serif / small grey)
─────────────────────────────────────────────────────────────────────────── */

const R1 = 1.0;
const C1 = new THREE.Vector3(2.2, 0.5, 0);
