  grad.addColorStop(1.00, rim);
  g.fillStyle = grad;
  g.beginPath(); g.arc(s / 2, s / 2, s / 2 - 1, 0, Math.PI * 2); g.fill();
  const t = new THREE.CanvasTexture(cv);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
function makePlusTex() {
  const s = 64, cv = document.createElement('canvas'); cv.width = cv.height = s;
  const g = cv.getContext('2d');
  g.strokeStyle = '#141414'; g.lineWidth = s * 0.15; g.lineCap = 'butt';
  g.beginPath();
  g.moveTo(s * 0.5, s * 0.14); g.lineTo(s * 0.5, s * 0.86);
  g.moveTo(s * 0.14, s * 0.5); g.lineTo(s * 0.86, s * 0.5);
  g.stroke();
  const t = new THREE.CanvasTexture(cv);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
const plusTex = makePlusTex();

/* ── spheres ──────────────────────────────────────────────────────────── */
const geoBig = new THREE.SphereGeometry(1, 64, 48);
const geoSm = new THREE.SphereGeometry(1, 48, 36);

const mat1 = new THREE.MeshMatcapMaterial({ matcap: makeMatcap('#f7f8fd', '#e2e6f5', '#9aa6d4') });
const mat2 = new THREE.MeshMatcapMaterial({ matcap: makeMatcap('#ffffff', '#f0f0f2', '#bfbfc6') });

const sph1 = new THREE.Mesh(geoBig, mat1); sph1.position.copy(C1); sph1.scale.setScalar(R1); scene.add(sph1);
const sph2 = new THREE.Mesh(geoSm, mat2); sph2.position.copy(C2); sph2.scale.setScalar(R2v); scene.add(sph2);

/* subtle selection rim (thin, muted — not a coloured halo) */
function rimMat() {
  return new THREE.MeshBasicMaterial({ color: 0x4a63b4, side: THREE.BackSide, transparent: true, opacity: 0.55 });
}
const rim1 = new THREE.Mesh(geoBig, rimMat()); rim1.position.copy(C1); rim1.visible = false; scene.add(rim1);
const rim2 = new THREE.Mesh(geoSm, rimMat()); rim2.position.copy(C2); rim2.visible = false; scene.add(rim2);

/* centre dots — drawn over the sphere so they read like the flat figure */
const dotMat = new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false, depthWrite: false });
const dot1 = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 12), dotMat);
dot1.position.copy(C1); dot1.scale.setScalar(0.035); dot1.renderOrder = 5; scene.add(dot1);
const dot2 = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 12), dotMat);
dot2.position.copy(C2); dot2.renderOrder = 5; scene.add(dot2);

/* ── radius arrows (always visible on top of the sphere, as in the book) ─ */
function buildArrow() {
  const g = new THREE.Group();
  const m = new THREE.MeshBasicMaterial({ color: 0x0b0b0b, depthTest: false, depthWrite: false });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 12), m);
  const head = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 18), m);
  shaft.renderOrder = 5; head.renderOrder = 5;
  g.add(shaft, head);
  g.userData = { shaft, head };
  scene.add(g);
  return g;
}
const arrow1 = buildArrow(), arrow2 = buildArrow();
const YAX = new THREE.Vector3(0, 1, 0);
function setArrow(g, center, dir, len, thick, headLen) {
  const hL = Math.min(headLen, len * 0.36);
  const sL = Math.max(0.001, len - hL);
  const { shaft, head } = g.userData;
  shaft.scale.set(thick, sL, thick); shaft.position.set(0, sL / 2, 0);
  head.scale.set(thick * 3.2, hL, thick * 3.2); head.position.set(0, sL + hL / 2, 0);
  g.position.copy(center);
  g.quaternion.setFromUnitVectors(YAX, dir.clone().normalize());
}
const A1DIR = new THREE.Vector3(Math.cos(0.611), Math.sin(0.611), 0).normalize();     // +35°
const A2DIR = new THREE.Vector3(Math.cos(-2.182), Math.sin(-2.182), 0).normalize();   // -125°

/* ── '+' charge sprites ───────────────────────────────────────────────── */
const plusA = [], plusB = [], fadeA = [], fadeB = [];
function newPlus(size, at) {
  const m = new THREE.SpriteMaterial({ map: plusTex, transparent: true, opacity: 0, depthTest: false, depthWrite: false });
  const s = new THREE.Sprite(m);
  s.scale.set(size, size, 1);
  s.position.copy(at);
  s.renderOrder = 7;
  scene.add(s);
  return { sprite: s, target: at.clone(), targetOp: 1, size };
}
function ringDir(i, N) {
  const th = (i / N) * Math.PI * 2 + 0.35;
  const ph = 0.42 * Math.sin(2 * th + 0.9);
  return new THREE.Vector3(Math.cos(th) * Math.cos(ph), Math.sin(th) * Math.cos(ph), Math.sin(ph));
}
function setPluses(list, fadeList, center, R, N, size) {
  while (list.length < N) list.push(newPlus(size, center));
  while (list.length > N) { const p = list.pop(); p.targetOp = 0; fadeList.push(p); }
  for (let i = 0; i < N; i++) {
    list[i].target.copy(center).addScaledVector(ringDir(i, N), R * 1.05);
    list[i].targetOp = 1;
    list[i].size = size;
  }
}
function tweenList(list, dt) {
  for (const p of list) {
    p.sprite.position.lerp(p.target, Math.min(1, dt * 8));
    const m = p.sprite.material;
    m.opacity += (p.targetOp - m.opacity) * Math.min(1, dt * 8);
    const cs = p.sprite.scale.x, ns = cs + (p.size - cs) * Math.min(1, dt * 8);
    p.sprite.scale.set(ns, ns, 1);
  }
}
function reapFades(fadeList) {
  for (let i = fadeList.length - 1; i >= 0; i--) {
    if (fadeList[i].sprite.material.opacity < 0.02) {
      scene.remove(fadeList[i].sprite);
      fadeList[i].sprite.material.dispose();
      fadeList.splice(i, 1);
    }
  }
}

/* ── wire ─────────────────────────────────────────────────────────────── */
const W1DIR = new THREE.Vector3(-0.988, -0.156, 0).normalize();
const W2DIR = new THREE.Vector3(0.813, 0.582, 0).normalize();
const wireMatA = new THREE.MeshBasicMaterial({ color: 0x8a8a8a, transparent: true, opacity: 1 });
const wireMatB = new THREE.MeshBasicMaterial({ color: 0x8a8a8a, transparent: true, opacity: 1 });
const wireA = new THREE.Mesh(new THREE.BufferGeometry(), wireMatA); scene.add(wireA);
const wireB = new THREE.Mesh(new THREE.BufferGeometry(), wireMatB); scene.add(wireB);

function subTube(curve, t0, t1, mesh) {
  if (t1 - t0 < 0.02) { mesh.visible = false; return; }
  mesh.visible = true;
  const pts = [];
  for (let i = 0; i <= 24; i++) pts.push(curve.getPoint(t0 + (t1 - t0) * i / 24));
  const c = new THREE.CatmullRomCurve3(pts);
  const g = new THREE.TubeGeometry(c, 40, 0.015, 8, false);
  mesh.geometry.dispose();
  mesh.geometry = g;
}
function updateWire() {
  const P1 = C1.clone().addScaledVector(W1DIR, R1 * 0.99);
  const P2 = C2.clone().addScaledVector(W2DIR, R2v * 0.99);
  const ctrl = P1.clone().add(P2).multiplyScalar(0.5).add(new THREE.Vector3(0, -0.5, 0));
  const curve = new THREE.QuadraticBezierCurve3(P1, ctrl, P2);
  const gap = 0.5 * wireT;
  subTube(curve, 0, 0.5 - gap, wireA);
  subTube(curve, 0.5 + gap, 1, wireB);
  const op = 1 - wireT;
  wireMatA.opacity = op; wireMatB.opacity = op;
  if (op < 0.02) { wireA.visible = false; wireB.visible = false; }
}

/* ── physics (k = 1, total charge = 1; σ in units where σ_large = 1 at ratio 3) ── */
const SIG_UNIT = 0.75;
function physics() {
  const R2 = R1 / ratio;
  let Q1, Q2, N1, N2;
  if (connected) {
    Q1 = R1 / (R1 + R2); Q2 = R2 / (R1 + R2);
    N1 = 14; N2 = Math.max(4, Math.round(14 * R2 / R1));
  } else {
    Q1 = frozen.Q1; Q2 = frozen.Q2; N1 = frozen.N1; N2 = frozen.N2;
  }
  return {
    R2, Q1, Q2, N1, N2,
    V1: Q1 / R1, V2: Q2 / R2,
    sg1: (Q1 / (R1 * R1)) / SIG_UNIT,
    sg2: (Q2 / (R2 * R2)) / SIG_UNIT
  };
}

/* ── labels ───────────────────────────────────────────────────────────── */
/* Camera first so the label-size compensation below sees the final pose.   */
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 8, rollDeg: 0, heightFraction: 0.6 });
camera.fov = 28; camera.updateProjectionMatrix();
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 8, rollDeg: 0, heightFraction: 0.6 });

const SER = 'font-family:Times New Roman,serif;font-style:italic;';
const LBL = [];
function mkLabel(html, base, opts) {
  const l = addLabel(html, new THREE.Vector3(), Object.assign({ fontSize: base + 'px' }, opts || {}));
  LBL.push({ l, base });
  return l;
}
/* Under perspective the scaffold shrinks labels by 8/distance; compensate so
   the on-screen size really is the base size (previously they read ~6px). */
function applyLabelScale() {
  const dist = Math.max(1, camera.position.distanceTo(controls.target));
  const k = dist / 8;
  for (const { l, base } of LBL) l.div.style.fontSize = (base * k).toFixed(1) + 'px';
}

const labR1 = mkLabel('<span style="' + SER + '">R</span><sub>1</sub>', 18, { offset: [18, 12], color: '#111' });
const labR2 = mkLabel('<span style="' + SER + '">R</span><sub>2</sub>', 16, { offset: [-20, -12], color: '#111' });
const labV1 = mkLabel('', 14, { color: '#2f3340' });
const labV2 = mkLabel('', 14, { color: '#2f3340' });
const labS1 = mkLabel('', 14, { color: '#2f3340' });
const labS2 = mkLabel('', 14, { color: '#2f3340' });
const labWire = mkLabel('', 12.5, { color: '#6f7480' });
applyLabelScale();
window.addEventListener('resize', () => setTimeout(applyLabelScale, 30));

function fmt(x, n) { return x.toFixed(n); }
function updateLabels(st) {
  labR1.pos.copy(C1).addScaledVector(A1DIR, R1 * 0.55);
  labR2.pos.copy(C2).addScaledVector(A2DIR, R2v * 0.62);

  labV1.pos.copy(C1).add(new THREE.Vector3(0, R1 + 0.34, 0));
  labV2.pos.copy(C2).add(new THREE.Vector3(0, R2v + 0.34, 0));
  labS1.pos.copy(C1).add(new THREE.Vector3(0, -R1 - 0.34, 0));
  labS2.pos.copy(C2).add(new THREE.Vector3(0, -R2v - 0.34, 0));

  labV1.div.innerHTML = '<i>V</i><sub>1</sub> = ' + fmt(st.V1, 2);
  labV2.div.innerHTML = '<i>V</i><sub>2</sub> = ' + fmt(st.V2, 2);
  labS1.div.innerHTML = '&sigma;<sub>1</sub> = ' + fmt(st.sg1, 2);
  labS2.div.innerHTML = '&sigma;<sub>2</sub> = ' + fmt(st.sg2, 2);

  const P1 = C1.clone().addScaledVector(W1DIR, R1);
  const P2 = C2.clone().addScaledVector(W2DIR, R2v);
  labWire.pos.copy(P1).add(P2).multiplyScalar(0.5).add(new THREE.Vector3(0, -0.46, 0));
  labWire.div.innerHTML = connected ? '<i>V</i><sub>1</sub> = <i>V</i><sub>2</sub>' : 'wire cut';
  labWire.div.style.opacity = connected ? String(1 - wireT) : '0.85';
}

/* ── readout ──────────────────────────────────────────────────────────── */
const readout = document.getElementById('readout');
function updateReadout(st) {
  const state = connected
    ? '<span style="color:#666">Connected: Q &prop; R, V₁ = V₂, σ &prop; 1/R</span>'
    : '<span style="color:#666">Isolated: charge frozen, V₁ ≠ V₂ in general</span>';
  if (selected === 0) {
    readout.innerHTML =
      '<b>Both conductors</b><br>' +
      'R₁ = ' + fmt(R1, 2) + ' &nbsp; Q₁ = ' + fmt(st.Q1, 3) + ' &nbsp; V₁ = ' + fmt(st.V1, 2) + ' &nbsp; σ₁ = ' + fmt(st.sg1, 2) + '<br>' +
      'R₂ = ' + fmt(st.R2, 3) + ' &nbsp; Q₂ = ' + fmt(st.Q2, 3) + ' &nbsp; V₂ = ' + fmt(st.V2, 2) + ' &nbsp; σ₂ = ' + fmt(st.sg2, 2) + '<br>' +
      '<span style="color:#1a5fb4">σ₂/σ₁ = ' + fmt(st.sg2 / st.sg1, 2) + '</span><br>' + state;
    return;
  }
  const big = selected === 1;
  const Rs = big ? R1 : st.R2, Ro = big ? st.R2 : R1;
  const Qs = big ? st.Q1 : st.Q2, Qo = big ? st.Q2 : st.Q1;
  const Vs = big ? st.V1 : st.V2, Vo = big ? st.V2 : st.V1;
  const Ss = big ? st.sg1 : st.sg2, So = big ? st.sg2 : st.sg1;
  readout.innerHTML =
    '<b>Selected: ' + (big ? 'large sphere (R₁)' : 'small sphere (R₂)') + '</b><br>' +
    'R = ' + fmt(Rs, 3) + ' &nbsp; Q = ' + fmt(Qs, 3) + '<br>' +
    'V = ' + fmt(Vs, 2) + ' &nbsp; σ = ' + fmt(Ss, 2) + '<br>' +
    '<span style="color:#666">other: R = ' + fmt(Ro, 3) + ', Q = ' + fmt(Qo, 3) +
    ', V = ' + fmt(Vo, 2) + ', σ = ' + fmt(So, 2) + '</span><br>' +
    '<span style="color:#1a5fb4">σ<sub>small</sub>/σ<sub>large</sub> = ' + fmt(st.sg2 / st.sg1, 2) + '</span><br>' + state;
}

/* ── main update ──────────────────────────────────────────────────────── */
function updateAll() {
  const st = physics();
  R2v = st.R2;

  sph2.scale.setScalar(R2v);
  rim1.scale.setScalar(R1 * 1.02);
  rim2.scale.setScalar(R2v * 1.035);
  rim1.visible = (selected === 1);
  rim2.visible = (selected === 2);

  dot2.scale.setScalar(Math.max(0.013, 0.06 * R2v));

  setArrow(arrow1, C1, A1DIR, R1 * 0.97, selected === 1 ? 0.020 : 0.012, 0.085);
  const t2 = Math.min(1, R2v * 2.6);
  setArrow(arrow2, C2, A2DIR, R2v * 0.95,
    (selected === 2 ? 0.020 : 0.012) * Math.max(0.55, t2), 0.085 * Math.max(0.5, t2));

  const szBig = 0.20;
  const szSm = szBig * (0.55 + 0.45 * Math.min(1, R2v / R1));
  setPluses(plusA, fadeA, C1, R1, st.N1, szBig);
  setPluses(plusB, fadeB, C2, R2v, st.N2, szSm);

  updateWire();
  updateLabels(st);
  updateReadout(st);
}

/* ── interaction: click to select ─────────────────────────────────────── */
function select(i) { selected = (selected === i) ? 0 : i; updateAll(); }
registerInteractive(sph1, {
  title: 'Large conductor (radius R₁)',
  tooltip: 'Large sphere — click for Q, V, σ',
  body: 'At a common potential this sphere holds the larger share of the charge (Q ∝ R), yet that charge is spread over a 4πR₁² surface, so its surface charge density σ = Q/4πR² is the SMALLER of the two.',
  onClick: () => select(1)
});
registerInteractive(sph2, {
  title: 'Small conductor (radius R₂)',
  tooltip: 'Small sphere — click for Q, V, σ',
  body: 'This sphere takes less total charge, but it is packed onto a much smaller area: σ ∝ 1/R, so σ₂/σ₁ = R₁/R₂. That is why small-radius points reach breakdown fields first.',
  onClick: () => select(2)
});

/* ── controls ─────────────────────────────────────────────────────────── */
const btnReset = document.getElementById('btnReset');
btnReset.style.display = '';
btnReset.textContent = 'Reset view';
btnReset.addEventListener('click', () => setTimeout(applyLabelScale, 30));

const slider = document.getElementById('radiusRatio');
const ratioVal = document.getElementById('ratioVal');
slider.addEventListener('input', () => {
  ratioTarget = parseFloat(slider.value);
  ratioVal.textContent = ratioTarget.toFixed(1);
});

const btnWire = document.getElementById('wireConnected');
function setConnected(on) {
  if (on === connected) return;
  if (!on) {
    const st = physics();
    frozen = { Q1: st.Q1, Q2: st.Q2, N1: st.N1, N2: st.N2 };
  }
  connected = on;
  wireTTarget = on ? 0 : 1;
  if (on) { wireA.visible = true; wireB.visible = true; }
  btnWire.textContent = 'Wire: ' + (on ? 'Connected (common potential)' : 'Separated');
  btnWire.classList.toggle('active', on);
  updateAll();
}
btnWire.addEventListener('click', () => setConnected(!connected));

/* ── demo steps ───────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'Equal spheres, connected', n: 'With R₁ = R₂ the wire equalizes the potentials: each sphere carries the same charge and the same surface charge density — the “+” signs are equally spaced on both.', r: 1, c: true },
  { t: 'The figure as drawn: R₁ = 3R₂', n: 'Grow the ratio to three. The wire keeps V₁ = V₂, so Q ∝ R: the big sphere holds three times the charge, yet its “+” signs are spread thinly while the small sphere’s are crowded three times as densely (σ₂/σ₁ = 3).', r: 3, c: true },
  { t: 'Push the ratio further', n: 'At R₁ = 6R₂ the contrast is extreme — the small sphere’s surface charge density, and therefore its surface field, is six times that of the large sphere. This is why sharp, small-radius points discharge first.', r: 6, c: true },
  { t: 'Cut the wire', n: 'Remove the wire and the spheres are isolated: charge can no longer flow, the frozen distributions stay put, and the two potentials are free to differ. Move the slider now — V₁ and V₂ drift apart.', r: 6, c: false }
];
let stepIdx = 1;
const elT = document.getElementById('stepTitle'), elN = document.getElementById('stepText');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  ratioTarget = s.r; slider.value = s.r; ratioVal.textContent = s.r.toFixed(1);
  setConnected(s.c);
  elT.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + s.t;
  elN.textContent = s.n;
}
document.getElementById('prevStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('nextStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
let playTimer = null;
const btnPlay = document.getElementById('playSteps');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = 'Play'; btnPlay.classList.remove('active'); }
}
btnPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  btnPlay.textContent = 'Pause'; btnPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 5200);
});

/* ── tween loop ───────────────────────────────────────────────────────── */
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000); _last = now;
  let dirty = false;
  if (Math.abs(ratio - ratioTarget) > 1e-4) { ratio += (ratioTarget - ratio) * Math.min(1, dt * 7); dirty = true; }
  else if (ratio !== ratioTarget) { ratio = ratioTarget; dirty = true; }
  if (Math.abs(wireT - wireTTarget) > 1e-3) { wireT += (wireTTarget - wireT) * Math.min(1, dt * 5); dirty = true; }
  else if (wireT !== wireTTarget) { wireT = wireTTarget; dirty = true; }
  if (dirty) updateAll();
  tweenList(plusA, dt); tweenList(plusB, dt);
  tweenList(fadeA, dt); tweenList(fadeB, dt);
  reapFades(fadeA); reapFades(fadeB);
}

/* ── init ─────────────────────────────────────────────────────────────── */
updateAll();
goToStep(1);
tick();
// @FIGURE_CODE_END

